#[derive(Debug, Clone, PartialEq)]
pub enum FormField {
    String(FormStringField),
    Number(FormNumberField),
    Integer(FormIntegerField),
    Boolean(FormBooleanField),
    Multiselect(FormMultiselectField),
    External(FormExternalField),
}

impl crate::codec::Decode for FormField {
    fn decode(value: &Value, path: &mut crate::codec::Path) -> Result<Self, crate::codec::DecodeError> {
        let object = crate::codec::as_object(value, path)?;
        let tag: String = crate::codec::decode_field(object, "type", path)?;
        match tag.as_str() {
            "string" => <FormStringField as crate::codec::Decode>::decode(value, path).map(Self::String),
            "number" => <FormNumberField as crate::codec::Decode>::decode(value, path).map(Self::Number),
            "integer" => <FormIntegerField as crate::codec::Decode>::decode(value, path).map(Self::Integer),
            "boolean" => <FormBooleanField as crate::codec::Decode>::decode(value, path).map(Self::Boolean),
            "multiselect" => <FormMultiselectField as crate::codec::Decode>::decode(value, path).map(Self::Multiselect),
            "external" => <FormExternalField as crate::codec::Decode>::decode(value, path).map(Self::External),
            _ => Err(path.at("expected a known type")),
        }
    }
}

impl crate::codec::Encode for FormField {
    fn encode(&self, out: &mut String) {
        match self {
            Self::String(value) => <FormStringField as crate::codec::Encode>::encode(value, out),
            Self::Number(value) => <FormNumberField as crate::codec::Encode>::encode(value, out),
            Self::Integer(value) => <FormIntegerField as crate::codec::Encode>::encode(value, out),
            Self::Boolean(value) => <FormBooleanField as crate::codec::Encode>::encode(value, out),
            Self::Multiselect(value) => <FormMultiselectField as crate::codec::Encode>::encode(value, out),
            Self::External(value) => <FormExternalField as crate::codec::Encode>::encode(value, out),
        }
    }
}

