#[derive(Debug, Clone, PartialEq)]
pub enum FormValue {
    String(String),
    Number(f64),
    Bool(bool),
    Array(Vec<String>),
}

impl crate::codec::Decode for FormValue {
    fn decode(value: &Value, path: &mut crate::codec::Path) -> Result<Self, crate::codec::DecodeError> {
        let mark = path.mark();
        let member = <String as crate::codec::Decode>::decode(value, path);
        path.truncate(mark);
        if let Ok(member) = member {
            return Ok(Self::String(member));
        }
        let mark = path.mark();
        let member = <f64 as crate::codec::Decode>::decode(value, path);
        path.truncate(mark);
        if let Ok(member) = member {
            return Ok(Self::Number(member));
        }
        let mark = path.mark();
        let member = <bool as crate::codec::Decode>::decode(value, path);
        path.truncate(mark);
        if let Ok(member) = member {
            return Ok(Self::Bool(member));
        }
        let mark = path.mark();
        let member = <Vec<String> as crate::codec::Decode>::decode(value, path);
        path.truncate(mark);
        if let Ok(member) = member {
            return Ok(Self::Array(member));
        }
        Err(path.at("no member matched"))
    }
}

impl crate::codec::Encode for FormValue {
    fn encode(&self, out: &mut String) {
        match self {
            Self::String(value) => <String as crate::codec::Encode>::encode(value, out),
            Self::Number(value) => <f64 as crate::codec::Encode>::encode(value, out),
            Self::Bool(value) => <bool as crate::codec::Encode>::encode(value, out),
            Self::Array(value) => <Vec<String> as crate::codec::Encode>::encode(value, out),
        }
    }
}

